const config = Object.freeze({ mode: "dark", tags: [] });
const user = Object.create(config);

try {
  user.mode = "light";
} catch (error) {
  console.log(error.name);
}

user.tags.push("beta");
user.level = 3;

console.log(user.mode, config.tags.length, Object.hasOwn(user, "level"));

Object.defineProperty(user, "mode", { value: "light" });

console.log(user.mode, config.mode);
